  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kTransparent:
      return mojo::Equals(data_.transparent, other.data_.transparent);
    case Tag::kOpaque:
      return mojo::Equals(data_.opaque, other.data_.opaque);
  }

